package net.mcreator.minepiece.procedures;
import java.util.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.*;
import net.fabricmc.fabric.api.networking.v1.ServerPlayConnectionEvents;
import net.mcreator.minepiece.entity.*;
import net.mcreator.minepiece.init.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.*;
import net.minecraft.world.item.*;
import net.minecraft.world.phys.*;
import net.minecraft.world.level.ClipContext;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.resources.Identifier;
/** B05 source-shaped finite attacks. Explicit adaptations and original traces: BATCH-05.md. */
public final class MythicBatchTechniques {
 public static final Item[] FRUITS={MinepieceModItems.ITEM_DEVIL_FRUIT_KAGE_KAGE,MinepieceModItems.ITEM_DEVIL_FRUIT_SORU_SORU,MinepieceModItems.ITEM_DEVIL_FRUIT_UTA_UTA,MinepieceModItems.ITEM_DEVIL_FRUIT_IMU,MinepieceModItems.ITEM_DEVIL_FRUIT_GOMU_GOMU};
 public static final String[] NAMES={"kage","soru","uta","imu","gomu"};
 private static final Identifier ASGARD=Identifier.fromNamespaceAndPath("minepiece","b05_asgard_scale");
 private static final class Action {final ServerPlayer owner;final ServerLevel world;final Item fruit;final DevilFruitMove move;final TechniqueTerrain.Budget terrain;final Set<UUID> hits=new HashSet<>();Vec3 look,start;int age;boolean landed,stopped;Action(ServerPlayer p,Item f,DevilFruitMove m){owner=p;world=(ServerLevel)p.level();fruit=f;move=m;look=p.getLookAngle();start=p.position();terrain=TechniqueTerrain.begin(p,m);}}
 public static final class Shot {final Action action;final double radius,damage;final Set<UUID> hits;Shot(Action a,double r,double damage,boolean separate){action=a;radius=r;this.damage=damage;hits=separate?new HashSet<>():a.hits;}public boolean valid(){return BatchRules.usable(action.owner,action.world,action.fruit);}}
 private record Companion(Action action,String kind){}
 private record Maintained(Action action,long until){}
 private static final Map<UUID,Action> ACTIVE=new HashMap<>();private static final Map<EntityGomuArmEntity,Action> VISUALS=new HashMap<>();private static final List<SkillProjectileEntity> SHOTS=new ArrayList<>();private static final Map<SummonEntity,Companion> SUMMONS=new HashMap<>();private static final Map<UUID,Maintained> ASGARDS=new HashMap<>(),SHIELDS=new HashMap<>();
 private MythicBatchTechniques(){}
 public static boolean handles(ItemStack f){return Arrays.asList(FRUITS).contains(f.getItem());}
 public static String shortName(Item f){return NAMES[Arrays.asList(FRUITS).indexOf(f)];}
 public static String animationFor(ServerPlayer p,String id){var f=DevilFruitPowerLogic.getDevilFruit(p);return handles(f)?"b05_"+shortName(f.getItem())+"_"+id:"";}
 public static int windup(String id){return Set.of("gear_change","shadowasgard","summontotmusica","noteshield","posing","islandshatterpunch","ikoku").contains(id)?20:id.equals("attackoverhead")?14:10;}
 public static int activeCount(){return ACTIVE.size();}public static int shotCount(){SHOTS.removeIf(Entity::isRemoved);return SHOTS.size();}public static int summonCount(ServerPlayer p){return (int)SUMMONS.entrySet().stream().filter(e->!e.getKey().isRemoved()&&e.getValue().action.owner==p).count();}
 public static boolean owned(SummonEntity e){return SUMMONS.containsKey(e);}public static boolean summonValid(SummonEntity e){var c=SUMMONS.get(e);return c!=null&&BatchRules.usable(c.action.owner,c.action.world,c.action.fruit);}
 public static boolean summonTarget(SummonEntity e,LivingEntity t){var c=SUMMONS.get(e);return c!=null&&summonValid(e)&&BatchRules.offensiveTarget(c.action.owner,t)&&e.hasLineOfSight(t);}
 public static boolean totRoom(ServerPlayer p){var box=new AABB(p.getX()-1.2,p.getY(),p.getZ()-1.2,p.getX()+1.2,p.getY()+3.6,p.getZ()+1.2);return GoroAmaru.safeVolume((ServerLevel)p.level(),box)&&p.level().noCollision(p,box.deflate(.001));}
 public static boolean cast(ServerPlayer p,ItemStack f,DevilFruitMove m){if(!(p.level() instanceof ServerLevel l)||!handles(f)||!BatchRules.usable(p,l,f.getItem())||ACTIVE.containsKey(p.getUUID()))return false;
  if(m.id().equals("summontotmusica")&&!totRoom(p))return false;
  if(m.id().equals("gear_change")&&!GomuGears.canCycle(p)||m.id().equals("shadowasgard")&&ASGARDS.containsKey(p.getUUID())||m.id().equals("noteshield")&&SHIELDS.containsKey(p.getUUID()))return false;
  if(Set.of("doppelman","summontotmusica","notewarrior").contains(m.id())&&SUMMONS.entrySet().stream().anyMatch(e->!e.getKey().isRemoved()&&e.getValue().action.owner==p&&e.getValue().kind.equals(m.id())))return false;
  var a=new Action(p,f.getItem(),m);ACTIVE.put(p.getUUID(),a);fx(a,"b05_"+shortName(a.fruit)+"_charge",p.getEyePosition().add(p.getLookAngle()),windup(m.id())+1,.2);return true;}
 private static String profile(Action a){return "b05_"+shortName(a.fruit)+"_"+a.move.id();}
 private static Vec3 flat(Vec3 v){var f=new Vec3(v.x,0,v.z);return f.lengthSqr()<.0001?new Vec3(0,0,1):f.normalize();}
 private static EntityGomuArmEntity fx(Action a,String id,Vec3 at,int ttl,double size){var e=GoroTechniques.visual(a.owner,id,at,ttl);e.setStretch((float)size);VISUALS.put(e,a);return e;}
 private static void endAsgard(ServerPlayer p){var f=ASGARDS.get(p.getUUID());if(f==null||f.action.owner!=p)return;ASGARDS.remove(p.getUUID(),f);var scale=p.getAttribute(Attributes.SCALE);if(scale!=null)scale.removeModifier(ASGARD);p.refreshDimensions();ShadowLedger.restoreAll(p,"echeance");}
 public static void cancel(ServerPlayer p){var a=ACTIVE.get(p.getUUID());if(a!=null&&a.owner==p)ACTIVE.remove(p.getUUID(),a);VISUALS.entrySet().removeIf(e->{if(e.getValue().owner!=p)return false;e.getKey().discard();return true;});for(var e:SHOTS)if(e.mythicShot.action.owner==p)e.discard();SUMMONS.entrySet().removeIf(e->{if(e.getValue().action.owner!=p)return false;e.getKey().discard();return true;});var shield=SHIELDS.get(p.getUUID());if(shield!=null&&shield.action.owner==p)SHIELDS.remove(p.getUUID(),shield);endAsgard(p);ImuCommand.cancel(p);GomuGears.end(p);ShadowLedger.restoreAll(p,"retrait");SoruSummons.releaseAll(p,"retrait");UtaDomain.exit(p,"retrait");}
 public static void clearAll(){var owners=new HashSet<ServerPlayer>();ACTIVE.values().forEach(a->owners.add(a.owner));VISUALS.values().forEach(a->owners.add(a.owner));SUMMONS.values().forEach(c->owners.add(c.action.owner));ASGARDS.values().forEach(c->owners.add(c.action.owner));SHIELDS.values().forEach(c->owners.add(c.action.owner));SHOTS.forEach(e->owners.add(e.mythicShot.action.owner));owners.forEach(MythicBatchTechniques::cancel);SHOTS.clear();GomuGears.clear();ImuCommand.clear();}
 public static void register(){ServerTickEvents.END_SERVER_TICK.register(s->tick());ServerPlayConnectionEvents.DISCONNECT.register((h,s)->cancel(h.player));ServerLifecycleEvents.SERVER_STOPPING.register(s->clearAll());}
 public static boolean shielded(ServerPlayer p){var c=SHIELDS.get(p.getUUID());return c!=null&&c.action.owner==p&&BatchRules.usable(p,c.action.world,c.action.fruit);}
 public static void tick(){GomuGears.tick();ImuCommand.tick();
  VISUALS.entrySet().removeIf(e->{if(!BatchRules.usable(e.getValue().owner,e.getValue().world,e.getValue().fruit))e.getKey().discard();return e.getKey().isRemoved();});SHOTS.removeIf(e->{if(!e.mythicShot.valid())e.discard();return e.isRemoved();});
  for(var entry:new ArrayList<>(ASGARDS.entrySet())){var f=entry.getValue();if(!BatchRules.usable(f.action.owner,f.action.world,f.action.fruit)||f.until<=f.action.world.getGameTime())endAsgard(f.action.owner);else ShadowLedger.tick(f.action.owner);}
  SHIELDS.entrySet().removeIf(e->{var c=e.getValue();return c.until<=c.action.world.getGameTime()||!BatchRules.usable(c.action.owner,c.action.world,c.action.fruit);});
  for(var entry:new ArrayList<>(SUMMONS.entrySet())){var e=entry.getKey();var c=entry.getValue();if(!summonValid(e))e.discard();if(e.isRemoved()){SUMMONS.remove(e);continue;}if(Set.of("raitei","hebunrifire").contains(c.kind)){var side=flat(c.action.owner.getLookAngle()).cross(new Vec3(0,1,0)).scale(c.kind.equals("raitei")?-1.5:1.5);e.setPos(c.action.owner.position().add(side).add(0,1.7,0));e.setDeltaMovement(Vec3.ZERO);}if(e.tickCount%20==0&&e.getModel().equals("tot_musica_1")){var a=c.action;var nearest=a.world.getEntitiesOfClass(LivingEntity.class,e.getBoundingBox().inflate(12)).stream().filter(t->BatchRules.offensiveTarget(a.owner,t)).min(Comparator.comparingDouble(e::distanceToSqr));nearest.ifPresent(t->{var origin=e.getEyePosition();spawnShot(a,"b05_uta_energy",.7,1.5,t.getBoundingBox().getCenter().subtract(origin).normalize(),origin,18,true);e.setAnimation("punch_right");});}}

  for(var a:new ArrayList<>(ACTIVE.values())){if(!BatchRules.usable(a.owner,a.world,a.fruit)){cancel(a.owner);continue;}int t=++a.age-windup(a.move.id());String id=a.move.id();if(t<0)continue;if(t==0){a.look=a.owner.getLookAngle();a.start=a.owner.position();TechniqueAnimations.playNamed(a.owner,profile(a)+"_release");release(a);}
   if(a.fruit==FRUITS[4]&&GomuArmStrike.handles(id)){int cycle=t/12,phase=t%12;if(cycle<GomuArmStrike.impacts(id)){if(phase==0)arm(a,cycle);if(phase==5)elasticHit(a);}}
   if(id.equals("brickbat")&&t%6==0&&t<=12)shoot(a,"b05_kage_brickbat",.6,.9,0);
   if(id.equals("noteattack")&&t%6==0&&t<=12)shoot(a,profile(a),.6,1.2,0);
   if(Set.of("tsunotokage","ikoku","posing","noteshield","furugora").contains(id)&&t<20&&!a.stopped)wave(a,t);
   if(id.equals("hebunrifire")&&t<10){ElementalBatchTechniques.blink(a.owner,flat(a.look),.5);strike(a,a.owner.position(),3,true,a.move.damage());if(t%2==0)fx(a,profile(a),a.owner.getEyePosition(),10,.7);if(t==9)a.terrain.impact(a.owner.position().add(flat(a.look)));}
   if(id.equals("mamaraid")&&t<28&&!a.landed){var to=a.start.add(flat(a.look).scale((t+1)*.25)).add(0,Math.sin((t+1)*Math.PI/28)*4,0);var d=to.subtract(a.owner.position());double moved=ElementalBatchTechniques.blink(a.owner,d,d.length());if(t==27||(moved+.05<d.length()&&t>=14)){a.landed=true;strike(a,a.owner.position(),5,false,a.move.damage());a.terrain.impact(a.owner.position().add(0,-.1,0));fx(a,"b05_soru_impact",a.owner.position(),24,4);}}
   if(id.equals("totmusicapunch")&&(t==5||t==17)){a.hits.clear();strike(a,a.owner.position(),a.move.range(),true,15);a.terrain.impact(a.owner.position().add(flat(a.look).scale(3)));var e=fx(a,"b05_native_tot_hand",a.owner.getEyePosition().add(flat(a.look).scale(2)),14,.1);e.setModel("tot_musica_hand");e.setTexture("tot_musica_1");e.setAnimation("punch");}
   if(t>=90)ACTIVE.remove(a.owner.getUUID(),a);
  }
 }
 private static void release(Action a){String id=a.move.id();
  a.world.playSound(null,a.owner.blockPosition(),a.fruit==FRUITS[2]?net.minecraft.sounds.SoundEvents.NOTE_BLOCK_HARP.value():net.minecraft.sounds.SoundEvents.PLAYER_ATTACK_SWEEP,net.minecraft.sounds.SoundSource.PLAYERS,.5F,a.fruit==FRUITS[2]?1.2F:1F);
  switch(id){
   case "gomu_pistol","gomu_bazooka","gomu_gatling","brickbat","noteattack","totmusicapunch","mamaraid","hebunrifire"->{if(id.equals("hebunrifire"))homie(a,SoruSummons.Kind.HEBUNRI);}
   case "gear_change"->GomuGears.cycle(a.owner,true);
   case "shadowasgard"->{for(var target:a.world.getEntitiesOfClass(LivingEntity.class,a.owner.getBoundingBox().inflate(6)))if(BatchRules.target(a.owner,target)&&!target.isInvulnerable())ShadowLedger.steal(a.owner,target);var attr=a.owner.getAttribute(Attributes.SCALE);if(attr!=null&&GiantForm.hasRoom(a.owner,1.5)){attr.addTransientModifier(new AttributeModifier(ASGARD,.5,AttributeModifier.Operation.ADD_VALUE));a.owner.refreshDimensions();}ASGARDS.put(a.owner.getUUID(),new Maintained(a,a.world.getGameTime()+600));fx(a,profile(a),a.owner.position(),30,2);}
   case "doppelman"->summon(a,id,"gecko_moria","gecko_moria",240,15,1);
   case "raitei"->{homie(a,SoruSummons.Kind.RAITEI);strike(a,a.owner.position(),a.move.range(),true,a.move.damage());a.terrain.impact(a.owner.position().add(flat(a.look).scale(3)));fx(a,profile(a),a.owner.position().add(flat(a.look).scale(3)),24,2.5);}
   case "notewarrior"->{summon(a,id,"note_warrior1","note_warrior1",200,15,-1);summon(a,id,"note_warrior2","note_warrior2",200,15,1);}
   case "summontotmusica"->{summon(a,id,"tot_musica_1","tot_musica_1",240,18,1);fx(a,profile(a),a.owner.position().add(0,.2,0),30,3);}
   case "noteshield"->{SHIELDS.put(a.owner.getUUID(),new Maintained(a,a.world.getGameTime()+80));fx(a,"b05_uta_guard",a.owner.getEyePosition().add(a.look.scale(1.2)),80,1.2);}
   case "posing","tsunotokage","ikoku","furugora"->{}
   case "notelaser"->{for(int i=-1;i<=1;i++)shoot(a,profile(a),.4,2.5,i*Math.PI/12);}
   case "silentcommand"->{for(var target:a.world.getEntitiesOfClass(LivingEntity.class,a.owner.getBoundingBox().inflate(8)))if(BatchRules.target(a.owner,target)&&!target.isInvulnerable())ImuCommand.apply(a.owner,target);fx(a,profile(a),a.owner.position(),30,4);}
   case "imuarrow"->{var strike=GomuArmStrike.resolve(a.owner,a.move);var e=fx(a,"b05_native_imu_arrow",a.owner.getEyePosition(),16,Math.max(.01,strike.distance()/12.25));e.setModel("b05_elastic_arm");e.setTexture("imu_arrow");e.setAnimation("punch_gomu_pistol2");}
   default->{strike(a,a.owner.position(),a.move.range(),!id.equals("attacksweep"),a.move.damage());a.terrain.impact(a.owner.position().add(flat(a.look).scale(id.equals("islandshatterpunch")?4:2)));fx(a,profile(a),a.owner.position().add(flat(a.look).scale(2)),24,id.equals("islandshatterpunch")?4:1.5);}
  }
  if(id.equals("imuarrow")){strike(a,a.owner.position(),a.move.range(),true,a.move.damage());a.terrain.impact(GomuArmStrike.resolve(a.owner,a.move).point());}
 }
 private static void homie(Action a,SoruSummons.Kind kind){var e=SoruSummons.summon(a.owner,kind);if(e!=null){e.setNoAi(true);e.setNoGravity(true);SUMMONS.put(e,new Companion(a,kind.moveId()));}}
 private static void summon(Action a,String kind,String model,String texture,int ttl,double damage,int side){var e=new SummonEntity(MinepieceModEntities.SUMMON,a.world);e.setOwnerEntity(a.owner);e.setModel(model);e.setTexture(texture);e.lifetime(ttl);e.setDamage(damage);Vec3 at=a.owner.position().add(flat(a.look).cross(new Vec3(0,1,0)).scale(side));if(model.equals("tot_musica_1")){for(double distance=.5;distance<=6;distance+=.5){Vec3 candidate=a.owner.position().add(flat(a.look).scale(distance));var box=new AABB(candidate.x-1.2,candidate.y,candidate.z-1.2,candidate.x+1.2,candidate.y+3.6,candidate.z+1.2);if(!GoroAmaru.safeVolume(a.world,box)||!a.world.noCollision(a.owner,box.deflate(.001)))break;at=candidate;}}else at=at.add(flat(a.look).scale(2));e.setPos(at);e.setOrder(SummonEntity.Order.ATTAQUER);if(model.equals("tot_musica_1"))e.setNoAi(true);SUMMONS.put(e,new Companion(a,kind));a.world.addFreshEntity(e);}
 private static void arm(Action a,int cycle){var s=GomuArmStrike.resolve(a.owner,a.move);var e=fx(a,"b05_native_gomu_"+a.move.id(),a.owner.getEyePosition(),12,Math.max(.01,s.distance()/(a.move.id().equals("gomu_gatling")?10.25:12.25)));e.setThickness(GomuGears.gear(a.owner)>=4?1.75F:1F);e.setTexture(GomuGears.gear(a.owner)==4?"tex_white2":GomuGears.gear(a.owner)==5?"tex_white3":"luffy");e.setModel("b05_elastic_arm");e.setAnimation(a.move.id().equals("gomu_bazooka")?"b05_bazooka":a.move.id().equals("gomu_gatling")?(cycle%2==0?"punch_gomu_gatling_right":"punch_gomu_gatling_left"):"punch_gomu_pistol");if(GomuGears.gear(a.owner)==3)e.setAnimation(a.move.id().equals("gomu_gatling")?"b05_gatling_third":"b05_pistol_third");}
 private static void elasticHit(Action a){var s=GomuArmStrike.resolve(a.owner,a.move);var target=s.target();if(target!=null&&BatchRules.target(a.owner,target)){var source=a.world.damageSources().playerAttack(a.owner);if(CombatSkillLogic.hurtAndConfirm(target,a.world,source,(float)a.move.damage()))CombatSkillLogic.applySkillKnockback(target,a.look,source,a.move.knockback());}a.terrain.impact(s.point());}
 private static void wave(Action a,int t){String id=a.move.id();double range=id.equals("tsunotokage")?12:Math.min(20,a.move.range()),distance=(t+1)*range/20;Vec3 from=a.start.add(0,id.equals("tsunotokage")?.15:1.2,0),to=from.add(flat(a.look).scale(distance));var collision=a.world.clip(new ClipContext(from,to,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,a.owner));if(collision.getType()!=HitResult.Type.MISS){a.stopped=true;a.terrain.impact(collision.getLocation());return;}double radius=id.equals("ikoku")?2:id.equals("tsunotokage")?.8:2.5;strike(a,to,radius,false,a.move.damage());a.terrain.impact(to);if(t%2==0)fx(a,profile(a),to,10,radius);}
 private static void strike(Action a,Vec3 center,double radius,boolean cone,double damage){var source=CombatSkillLogic.elementalDamageSource(a.world,a.fruit==FRUITS[1]&&a.move.id().equals("hebunrifire")?ElementType.FIRE:a.fruit==FRUITS[1]&&Set.of("raitei","furugora").contains(a.move.id())?ElementType.LIGHTNING:ElementType.PHYSICAL,a.owner,null);for(var target:a.world.getEntitiesOfClass(LivingEntity.class,new AABB(center,center).inflate(radius))){if(a.hits.contains(target.getUUID())||target.getBoundingBox().distanceToSqr(center)>radius*radius||!BatchRules.target(a.owner,target))continue;if(cone&&target.getBoundingBox().getCenter().subtract(a.owner.getEyePosition()).normalize().dot(a.look)<CombatSkillLogic.MELEE_CONE_COS)continue;if(CombatSkillLogic.hurtAndConfirm(target,a.world,source,(float)damage)){a.hits.add(target.getUUID());if(a.fruit==FRUITS[1]&&Set.of("raitei","furugora").contains(a.move.id()))ImuCommand.apply(a.owner,target,20);CombatSkillLogic.applySkillKnockback(target,target.position().subtract(a.owner.position()),source,a.move.knockback());}}}
 private static void shoot(Action a,String profile,double radius,double speed,double angle){var dir=a.look.yRot((float)angle);spawnShot(a,profile,radius,speed,dir,a.owner.getEyePosition().add(dir.scale(.4)),a.move.damage(),false);}
 private static void spawnShot(Action a,String profile,double radius,double speed,Vec3 dir,Vec3 at,double damage,boolean separate){var e=new SkillProjectileEntity(MinepieceModEntities.SKILL_PROJECTILE,at.x,at.y,at.z,dir,a.world);e.setOwner(a.owner);e.model("note_3d").texture("note_3d").visualProfile(profile).damage(damage).element(ElementType.PHYSICAL).lifetime(50).range(32).scale(.35F).trail(ParticleTypes.ASH);e.mythicShot=new Shot(a,radius,damage,separate);e.accelerationPower=0;e.shoot(dir.x,dir.y,dir.z,(float)speed,0);a.world.addFreshEntity(e);SHOTS.add(e);}

 public static void impact(SkillProjectileEntity e,Vec3 at,LivingEntity direct){var s=e.mythicShot;if(s==null||!s.valid())return;var a=s.action;var source=CombatSkillLogic.elementalDamageSource(a.world,ElementType.PHYSICAL,a.owner,e);for(var target:a.world.getEntitiesOfClass(LivingEntity.class,new AABB(at,at).inflate(s.radius))){if(s.hits.contains(target.getUUID())||!BatchRules.offensiveTarget(a.owner,target)||target.getBoundingBox().distanceToSqr(at)>s.radius*s.radius)continue;var ray=a.world.clip(new ClipContext(at,target.getBoundingBox().getCenter(),ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,a.owner));if(ray.getType()!=HitResult.Type.MISS)continue;if(CombatSkillLogic.hurtAndConfirm(target,a.world,source,(float)s.damage)){s.hits.add(target.getUUID());CombatSkillLogic.applySkillKnockback(target,e.getDeltaMovement(),source,a.move.knockback());}}a.terrain.impact(at);fx(a,"b05_"+shortName(a.fruit)+"_impact",at,16,.6);}
}
